"""Self-contained, offline commit reports. No fonts, scripts or telemetry fetched."""
import base64
import hashlib
import json

CSS = r"""
:root{--paper:#171d29;--card:#242d3c;--ink:#f5f7fa;--muted:#b1bfd0;--line:#455164;--accent:#ff9c31;--deep:#ffac4d;--mono:'Liberation Mono',Consolas,monospace;--sans:'Lato','Trebuchet MS',sans-serif;--display:'Lato','Arial Narrow',sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 var(--sans);background-image:linear-gradient(120deg,transparent 62%,#ffffff03 62%,#ffffff03 79%,transparent 79%)}button,select{font:inherit;color:inherit;min-height:44px}button{cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #61cfff;outline-offset:4px}a{color:inherit}.wrap{max-width:1320px;margin:auto;padding:0 48px}.skip{position:absolute;top:-90px;left:20px;background:#fff;color:#171d29;padding:12px;z-index:10}.skip:focus{top:10px}
.mast{background:#101620;border-bottom:3px solid var(--accent)}.mast .wrap{height:78px;display:flex;justify-content:space-between;align-items:center;gap:20px}.logo{display:flex;gap:15px;align-items:center;font:900 italic 30px var(--display);letter-spacing:-1px}.mark{display:flex;gap:4px;transform:skew(-16deg)}.mark i{width:9px;height:27px;background:var(--accent)}.mark i:last-child{height:19px;align-self:end;background:#fff}.edition{font:10px var(--mono);letter-spacing:1.5px;color:var(--muted)}.top-actions{display:flex;align-items:center;gap:22px}.quiet{background:transparent;border:1px solid #66758c;padding:8px 17px;text-transform:uppercase;font-size:11px;font-weight:900;letter-spacing:1px}.quiet:hover{background:#344155;border-color:#fff}
.modebar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:30px 0}.breadcrumb{color:var(--muted);font:11px var(--mono);max-width:45%;overflow-wrap:anywhere}.breadcrumb strong{color:var(--ink)}.switch{display:flex;gap:5px}.switch button{border:0;background:#303b4d;padding:12px 23px;font-weight:900;font-style:italic;text-transform:uppercase;letter-spacing:.7px;clip-path:polygon(8px 0,100% 0,calc(100% - 8px) 100%,0 100%)}.switch button[aria-pressed=true]{background:var(--accent);color:#171d29}.switch button:disabled{opacity:.4;cursor:default}
.intro{display:flex;justify-content:space-between;align-items:center;margin:24px 0 12px;gap:20px}.eyebrow,.label{font:11px var(--mono);letter-spacing:1.4px;text-transform:uppercase}.eyebrow{color:var(--muted)}.live{font:10px var(--mono);text-transform:uppercase;color:#b6d8ed;display:flex;align-items:center;gap:8px}.live:before{content:'';width:6px;height:6px;background:#7fe0ff}
.hero{display:grid;grid-template-columns:330px 1fr;background:#242e3e;min-height:350px;clip-path:polygon(0 0,calc(100% - 24px) 0,100% 24px,100% 100%,0 100%);position:relative}.hero:after{content:'';position:absolute;right:0;bottom:0;width:130px;height:5px;background:var(--accent)}.score-panel{background:#eef2f5;color:#202938;padding:28px 30px 25px;border-top:5px solid var(--accent);position:relative}.score-top{display:flex;justify-content:space-between;align-items:center;gap:10px}.score-top .label{font-size:10px}.pill{font:9px var(--mono);text-transform:uppercase;border:1px solid currentColor;padding:4px 7px;letter-spacing:.4px}.score-number{font:900 italic 108px/1.15 var(--display);letter-spacing:-7px;margin:20px 0 8px;font-variant-numeric:tabular-nums;white-space:nowrap}.score-number small{font:14px var(--mono);letter-spacing:0;margin-left:8px;color:#596579}.grade-line{display:flex;align-items:center;gap:12px}.grade{background:#26344a;color:#fff;display:inline-grid;place-items:center;min-width:31px;height:31px;font:900 italic 20px var(--display)}.grade-label{font-size:11px;text-transform:uppercase;font-weight:900;letter-spacing:.5px}.scale{display:flex;gap:3px;margin-top:25px}.scale span{height:7px;background:#c2cad4;flex:1;transform:skew(-20deg)}.scale .on{background:#ed8a1c}.scale-caption{display:flex;justify-content:space-between;font:8px var(--mono);margin-top:9px;color:#526074}.hero-compare{font-size:10px;margin-top:18px;color:#465369}.hero-compare strong{font-weight:900;color:#26344a}
.hero-copy{padding:35px 44px 26px;display:flex;flex-direction:column;justify-content:space-between;gap:22px;min-width:0}.hero-copy .eyebrow{color:var(--accent)}.hero-copy h1{font:900 italic clamp(32px,3.4vw,52px)/1.05 var(--display);letter-spacing:-1.8px;text-transform:uppercase;margin:14px 0 18px;max-width:750px;overflow-wrap:anywhere}.hero-copy p{font-size:12px;color:var(--muted);max-width:540px;margin:0}.commit-meta{display:flex;flex-wrap:wrap;align-items:center;gap:14px;padding-top:18px;border-top:1px solid var(--line);font:10px var(--mono);color:var(--muted)}.commit-id{border:1px solid #728197;background:transparent;padding:7px 12px;font:11px var(--mono);color:#fff;max-width:100%;overflow-wrap:anywhere}
.ladder-card{display:grid;grid-template-columns:1fr 1fr;background:#f4a33c;color:#182333;margin:10px 0 0;padding:22px 32px;gap:25px;position:relative;overflow:hidden}.ladder-card:after{content:'Σ';position:absolute;right:27px;top:-30px;font:900 italic 180px/1 var(--display);opacity:.075;pointer-events:none}.ladder-card .eyebrow{color:#293548;font-weight:bold}.ladder-number{font:900 italic 66px/1.05 var(--display);letter-spacing:-3px;margin:8px 0 4px;overflow-wrap:anywhere}.ladder-number small{font:900 15px var(--sans);letter-spacing:0;display:inline-block;margin-left:22px}.ladder-count{font:10px var(--mono);text-transform:uppercase;letter-spacing:1px}.ladder-context{align-self:center;position:relative;z-index:1}.ladder-context .equation{font:900 italic 22px var(--display);letter-spacing:-.5px}.ladder-context p{font-size:11px;max-width:390px;margin:8px 0}.ladder-context .small{color:#2c3c50}
.resource-row{display:grid;grid-template-columns:repeat(4,1fr);background:#1e2735;margin:10px 0 36px}.resource{padding:22px 25px;border-right:1px solid var(--line)}.resource:last-child{border:0}.resource .label{display:block;color:var(--muted);font-size:9px;letter-spacing:1px}.resource .number{display:block;font:900 italic 35px/1.4 var(--display);letter-spacing:-1px}.resource .hint{font-size:10px;color:var(--muted)}
.section-heading{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:32px 0 14px;border-bottom:1px solid var(--line);padding-bottom:12px}.section-heading h2{font:900 italic 25px var(--display);letter-spacing:-.6px;text-transform:uppercase;margin:0}.section-heading h2:before{content:'';display:inline-block;width:6px;height:19px;background:var(--accent);transform:skew(-16deg);margin-right:12px}.note{font:10px var(--mono);color:var(--muted)}.breakdown{display:grid;grid-template-columns:1.3fr 1fr;gap:10px}.panel{padding:25px 28px;background:#222c3b;border-top:2px solid #637187}.component{padding:14px 0;border-bottom:1px solid #3a4658}.component:first-child{padding-top:0}.component:last-child{padding-bottom:0;border:0}.component-head{display:flex;justify-content:space-between;gap:15px;font-size:13px;font-weight:700}.component-head strong{font:900 italic 22px var(--display)}.weight{font:10px var(--mono);margin-left:10px;color:var(--muted)}.meter{height:4px;background:#455064;margin:9px 0}.meter span{display:block;height:100%;background:var(--accent)}.component-foot{display:flex;justify-content:space-between;gap:12px;font-size:10px;color:var(--muted)}.aside-title{font:900 italic 21px var(--display);text-transform:uppercase;margin:0 0 15px}.confidence{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:15px}.confidence strong{font:900 italic 42px var(--display);color:var(--accent)}.small{font-size:11px;color:var(--muted)}.evidence-line{display:flex;justify-content:space-between;gap:14px;font-size:11px;margin:14px 0}.evidence-line b{font:11px var(--mono)}.explain{font-size:11px;color:#c4cfdd;border-left:3px solid #7f95b2;padding:10px 13px;background:#2c384a;margin:16px 0 0}
.history-stats{display:grid;grid-template-columns:repeat(4,1fr);margin:20px 0}.history-stat{padding:0 20px;border-right:1px solid var(--line)}.history-stat:first-child{padding-left:0}.history-stat:last-child{border:0}.history-stat span{display:block;font:10px var(--mono);color:var(--muted);text-transform:uppercase}.history-stat strong{font:900 italic 32px var(--display);display:block;margin:6px 0}.history-stat small{font-size:10px;color:var(--muted)}
.chart-panel{padding:20px 25px 10px;background:#1c2533}.chart-top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;font:10px var(--mono);color:var(--muted)}.chart-tabs{display:flex;gap:5px}.chart-tabs button{border:0;background:#334158;padding:8px 12px;font:900 10px var(--sans);letter-spacing:.5px;text-transform:uppercase}.chart-tabs button[aria-pressed=true]{color:#182333;background:var(--accent)}.chart{width:100%;height:230px;display:block;overflow:visible}.chart text{font:10px var(--mono);fill:#b1bfd0}.legend{display:flex;gap:18px;font-size:10px}.legend span:before{content:'';display:inline-block;width:7px;height:7px;background:var(--accent);margin-right:6px}.legend span:last-child:before{background:#c1cede}
.timeline-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:25px 0 12px}.timeline-toolbar h3{font:900 italic 20px var(--display);text-transform:uppercase;margin:0}.filters{display:flex;gap:12px}.filters select{border:1px solid #5c6b82;background:#263247;padding:7px 10px;font-size:11px;max-width:160px}.history-list{border-top:2px solid #7b8a9f}.history-row{width:100%;display:grid;grid-template-columns:80px 1fr 95px 100px 28px;align-items:center;gap:16px;border:0;border-bottom:1px solid #3c485b;background:#222c3b;text-align:left;padding:17px 16px}.history-row:nth-child(even){background:#1e2735}.history-row:hover{background:#35465e;box-shadow:inset 4px 0 var(--accent)}.hash{font:10px var(--mono);color:var(--accent)}.subject{font-size:12px;font-weight:700;overflow-wrap:anywhere}.date{font:10px var(--mono);color:var(--muted)}.row-score{font:900 italic 23px var(--display)}.row-rating{font:9px var(--mono);display:block;color:var(--muted);font-style:normal;white-space:nowrap}.row-grade{font:900 13px var(--sans);color:#d3deeb}.empty{padding:25px;color:var(--muted);font-size:12px;text-align:center;border:1px dashed #56647a}
.method{border-top:1px solid var(--line);margin-top:32px;padding:14px 0}.method summary{display:flex;align-items:center;gap:12px;list-style:none;min-height:44px;cursor:pointer;font-weight:900;text-transform:uppercase;font-size:11px;letter-spacing:.6px}.method summary:before{content:'+';font:22px var(--mono);color:var(--accent)}.method[open] summary:before{content:'−'}.method-body{display:grid;grid-template-columns:1fr 1fr;gap:30px;color:var(--muted);font-size:12px;padding:12px 0}.method code{font:11px var(--mono);overflow-wrap:anywhere}.footer{border-top:1px solid var(--line);padding:22px 0 32px;display:flex;justify-content:space-between;gap:24px;color:var(--muted)}.proof{font:9px/1.6 var(--mono);max-width:65%;overflow-wrap:anywhere}.footer-brand{font:900 italic 20px var(--display);white-space:nowrap}.footer-brand .small{font:10px var(--mono)}.demo-banner{font:10px var(--mono);text-transform:uppercase;text-align:center;padding:8px 20px;background:#303a4b;color:#d1dbe8}.latest-only .history-section,.latest-only .hero-compare{display:none!important}
dialog{border:1px solid #7e91aa;border-top:5px solid var(--accent);background:#222e40;color:var(--ink);padding:28px;max-width:min(600px,calc(100% - 32px))}dialog::backdrop{background:#060c16cc}dialog header{display:flex;justify-content:space-between;align-items:center;gap:15px}dialog h2{font:900 italic 30px var(--display);text-transform:uppercase;overflow-wrap:anywhere}dialog .dialog-score{font:900 italic 64px var(--display);color:var(--accent)}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);padding:14px 22px;background:#f4a33c;color:#172234;font-weight:900;font-size:12px;z-index:8;max-width:90%;overflow-wrap:anywhere}[hidden]{display:none!important}
.fade{animation:enter .35s ease-out both}@keyframes enter{from{opacity:0;transform:translateX(-10px)}to{opacity:1;transform:translateX(0)}}@media(prefers-reduced-motion:reduce){.fade{animation:none}}
@media(max-width:1000px){.wrap{padding:0 28px}.hero{grid-template-columns:290px 1fr}.score-panel{padding:23px}.score-number{font-size:96px}.hero-copy{padding:30px}.resource{padding:20px 17px}.hero-copy h1{font-size:37px}}
@media(max-width:720px){.wrap{padding:0 18px}.mast .wrap{height:68px}.edition{display:none}.logo{font-size:25px}.top-actions{gap:0}.quiet{padding:8px 11px}.modebar{flex-direction:column;align-items:stretch;gap:17px;margin:22px 0}.breadcrumb{max-width:100%}.switch button{flex:1;padding:11px 12px;font-size:12px}.intro{gap:12px;align-items:flex-start}.eyebrow,.live{font-size:9px}.hero{grid-template-columns:1fr;clip-path:none}.score-panel{padding:22px 26px}.score-number{font-size:105px;margin:8px 0}.scale{margin-top:17px}.hero-copy{padding:27px}.hero-copy h1{font-size:35px}.ladder-card{grid-template-columns:1fr;gap:15px;padding:23px 26px}.ladder-number{font-size:58px}.ladder-number small{font-size:12px;margin-left:15px}.ladder-context .equation{font-size:19px}.resource-row{grid-template-columns:1fr 1fr;margin-bottom:25px}.resource{padding:18px 20px;border-bottom:1px solid var(--line)}.resource:nth-child(2){border-right:0}.resource .number{font-size:30px}.breakdown{grid-template-columns:1fr}.panel{padding:22px}.component-foot{font-size:9px}.section-heading{align-items:flex-start}.section-heading h2{font-size:21px}.section-heading .note{max-width:40%;font-size:9px;text-align:right}.history-stats{grid-template-columns:1fr 1fr;row-gap:20px}.history-stat:nth-child(3){padding-left:0}.history-stat:nth-child(2){border:0}.chart-panel{padding:15px}.chart-top{gap:12px}.chart-tabs button{padding:7px;font-size:9px}.chart{height:180px}.legend{display:none}.timeline-toolbar{align-items:flex-start;flex-direction:column}.history-row{grid-template-columns:53px 1fr 70px 18px;gap:9px;padding:16px 10px}.history-row .date{display:none}.hash{font-size:9px}.subject{font-size:11px}.row-score{font-size:20px}.row-rating{font-size:8px}.method-body{grid-template-columns:1fr;gap:8px}.footer{flex-direction:column}.proof{max-width:100%}}
@media print{body{background:#fff;color:#172234;-webkit-print-color-adjust:exact;print-color-adjust:exact}.mast,.hero-copy,.panel,.resource-row,.history-list,.history-row,.method,.footer{color:#172234;background:#fff}.top-actions,.switch,.filters,.chart-tabs,dialog,.toast{display:none}.wrap{padding:0 14px;max-width:none}.hero,.panel,.history-row{break-inside:avoid}.hero-copy p,.small,.note,.component-foot,.proof,.date,.row-rating,.method-body{color:#465369}.fade{animation:none}.chart-panel{background:#222c3b}.history-stat span,.history-stat small{color:#465369}}
"""

JS = r"""
const data=JSON.parse(document.getElementById('report-data').textContent);
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=data.current,s=current.score,m=current.summary,e=s.evidence,stats=data.statistics||{},ladder=data.iteration;
const n=x=>x===null||x===undefined?'—':Number(x).toLocaleString('en-US',{maximumFractionDigits:1});
const short=x=>x===null||x===undefined?'—':Number(x)>=1e6?(Number(x)/1e6).toFixed(2)+'M':Number(x)>=1000?(Number(x)/1000).toFixed(1)+'K':n(x);
const pct=x=>x===null||x===undefined?'Not observed':Math.round(Number(x)*100)+'%';
const date=x=>new Date(x).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const words={S:'Exceptional consistency',A:'Strong process',B:'Steady progress',C:'Building momentum',D:'High iteration cost',E:'Significant rework'};
const textTokens=b=>b.tokens_complete===false?null:(b.tokens_estimated||0)+(b.tokens_measured||0);
const tokenLabel=b=>b.tokens_complete===false?'partial capture':b.tokens_estimated?'tokens (includes estimates)':'tokens';
const counts=m.event_counts||{},delta=stats.delta;
document.title=`${current.commit.slice(0,7)} · ${data.project} · AI-PoW`;
if(data.demo){const banner=document.createElement('div');banner.className='demo-banner';banner.textContent='INTERACTIVE DEMO · Synthetic commit history, evaluated with the production scoring algorithm.';document.body.prepend(banner)}
$('#content').innerHTML=`
<div class="modebar"><div class="breadcrumb">Workspace / <strong>${esc(data.project)}</strong></div><div class="switch" aria-label="Report view"><button id="iteration" aria-pressed="true" ${data.view==='latest'?'disabled':''}>Iteration history</button><button id="latest" aria-pressed="false">Latest commit</button></div></div>
<div class="intro"><span class="eyebrow">01 / Latest recorded commit</span><span class="live">${data.demo?'Demonstration data':data.verification.integrity_verified?'Trace integrity checked':'Integrity not checked'}</span></div>
<section class="hero fade" aria-label="Current commit score"><div class="score-panel"><div class="score-top"><span class="label">AI-POW SCORE</span><span class="pill">${esc(s.status)}</span></div><div class="score-number">${esc(s.value)}<small>/ 100</small></div><div class="grade-line"><span class="grade">${esc(s.grade)}</span><span class="grade-label">${esc(words[s.grade])}</span></div><div class="scale" aria-hidden="true">${Array.from({length:20},(_,i)=>`<span class="${i<Number(s.value)/5?'on':''}"></span>`).join('')}</div><div class="scale-caption"><span>MORE REWORK</span><span>MORE RETAINED WORK</span></div><div class="hero-compare">${delta===null||delta===undefined?'Your first comparable commit.':`<strong>${delta>=0?'+':''}${n(delta)} pts</strong> vs. previous scored commit`}</div></div>
<div class="hero-copy"><div><span class="eyebrow">Latest version / recorded</span><h1>${esc(current.title)}</h1><p>Observed work, retained changes, and resource use for this commit. Process measurements — not a code-quality verdict.</p></div><div class="commit-meta"><button class="commit-id" id="copy-commit" title="Copy full commit hash">↳ ${esc(current.commit.slice(0,10))}</button><span>${esc(date(current.date))}</span><span>${esc(s.cohort.toUpperCase())} SCOPE · ${n(e.scope.units)} units</span></div></div></section>
${ladder?`<section class="ladder-card history-section" aria-label="Cumulative project score"><div><span class="eyebrow">Total project score</span><div class="ladder-number">${n(ladder.value)}<small>+${n(ladder.delta)} THIS COMMIT</small></div><span class="ladder-count">${n(ladder.rated_commits)} SCORED COMMITS · STARTED AT 0</span></div><div class="ladder-context"><div class="equation">${n(ladder.previous)} + ${n(ladder.delta)} = ${n(ladder.value)}</div><p>Every recorded commit score, added as-is. No extra weights, deductions, tiers, or upper limit.</p><p class="small">${esc(ladder.algorithm)} · Full recorded first-parent history.</p></div></section>`:''}
<div class="resource-row"><div class="resource"><span class="label">HUMAN INPUT</span><span class="number">${short(textTokens(m.human))}</span><span class="hint">${tokenLabel(m.human)} · ${n(m.human.messages||m.human.events||0)} prompts</span></div><div class="resource"><span class="label">VISIBLE AI OUTPUT</span><span class="number">${short(textTokens(m.visible_ai))}</span><span class="hint">${tokenLabel(m.visible_ai)} · user-facing text</span></div><div class="resource"><span class="label">REFERENCE COMPUTE</span><span class="number">${!m.priced_calls?'—':'$'+Number(m.reference_usd_known_subtotal).toFixed(2)}</span><span class="hint">${m.reference_cost_complete_for_observed_calls?'':'Known subtotal · '}${n(m.priced_calls)} priced / ${n((m.priced_calls||0)+(m.unpriced_calls||0))} observed calls</span></div><div class="resource"><span class="label">AGENT ACTIVITY</span><span class="number">${n(counts['tool.call']||0)}</span><span class="hint">tool calls · ${n(counts['agent.spawn']||0)} sub-agents</span></div></div>
<div class="section-heading"><h2>Score breakdown</h2><span class="note">Four components / fixed weights</span></div><section class="breakdown" aria-label="Score breakdown"><div class="panel">${Object.entries(s.components).map(([key,c])=>`<div class="component"><div class="component-head"><span>${esc(c.label)}<span class="weight">${Math.round(Number(c.weight)*100)}%</span></span><strong>${c.ratio===null?'—':pct(c.ratio)}</strong></div><div class="meter"><span style="width:${Number(c.quality)*100}%"></span></div><div class="component-foot"><span>${key==='human'?'Temporal attribution proxy':key==='artifact'?'Compared with the committed tree':key==='task'?'Declared tasks with artifact evidence':'Scope-adjusted resource pressure'}</span><span>${pct(c.confidence)} evidence</span></div></div>`).join('')}</div><aside class="panel"><h3 class="aside-title">Capture overview</h3><div class="confidence"><div><span class="small">Evidence confidence</span><br><strong>${pct(s.confidence)}</strong></div><span class="pill">${esc(s.algorithm)}</span></div><div class="evidence-line"><span>Retained artifact operations</span><b>${n(e.artifact.retained)} / ${n(e.artifact.operations)}</b></div><div class="evidence-line"><span>Inputs linked to observed edits</span><b>${n(e.human.linked_prompts)} / ${n(e.human.prompts)}</b></div><div class="evidence-line"><span>Completed / declared task attempts</span><b>${n(e.task.completed)} / ${n(e.task.attempts)}</b></div><div class="evidence-line"><span>Changed files in this commit</span><b>${n(e.scope.files)}</b></div><p class="explain">${s.status==='provisional'?'This score is provisional. Sparse or missing evidence stays near a neutral 50 instead of becoming a perfect score.':'Enough evidence supports a more stable score. Additional observations still improve the reliability of the estimate.'} ${e.limited?'Some artifacts exceeded capture limits.':''}</p></aside></section>
<section class="history-section" aria-label="Iteration history"><div class="section-heading"><h2>Iteration history</h2><span class="note">Previous first-parent commits · up to 30</span></div><div class="history-stats"><div class="history-stat"><span>Average commit score</span><strong>${n(stats.average)}</strong><small>${n(stats.count||0)} prior scored commits</small></div><div class="history-stat"><span>Same-scope average</span><strong>${n(stats.peer_average)}</strong><small>${n(stats.peer_count||0)} ${esc(s.cohort)}-scope comparisons</small></div><div class="history-stat"><span>Local percentile</span><strong>${stats.percentile===null||stats.percentile===undefined?'—':n(stats.percentile)+'%'}</strong><small>${(stats.peer_count||0)<3?'Needs 3 comparable prior commits':'Within this repository and scope'}</small></div><div class="history-stat"><span>Same score grade</span><strong>${n(stats.same_grade||0)}</strong><small>Prior commits in grade ${esc(s.grade)}</small></div></div><div class="panel chart-panel"><div class="chart-top"><span id="chart-label">CUMULATIVE SCORE</span><div class="chart-tabs"><button id="chart-ladder" aria-pressed="true">Cumulative total</button><button id="chart-scores" aria-pressed="false">Commit scores</button></div><div class="legend"><span>Latest</span><span>Previous</span></div></div><div id="chart"></div></div><div class="timeline-toolbar"><h3>Recorded commits</h3><div class="filters"><label class="small">Grade <select id="grade-filter" aria-label="Filter history by grade"><option value="all">All grades</option>${['S','A','B','C','D','E'].map(g=>`<option value="${g}">Grade ${g}</option>`).join('')}</select></label><label class="small">Scope <select id="scope-filter" aria-label="Filter history by scope"><option value="all">All scopes</option><option value="same">Same scope</option></select></label></div></div><div class="history-list" id="journal"></div></section>
<details class="method"><summary>How the score is calculated</summary><div class="method-body"><div><p><strong>Retention contributes 70%.</strong> Input retention, artifact survival and task fulfillment use 40:40:20 proportions inside that share. Resource discipline supplies the remaining 30%.</p><p>Each observed retention ratio uses a Beta(2,2) prior. Evidence confidence grows gradually with observations. Missing dimensions retain their weight with neutral evidence; they are not silently removed.</p><p><code>score = 100 / (1 + exp(-5 × (L - 0.5)))</code></p></div><div><p><strong>L</strong> starts at 0.5 and adds each component's weighted, confidence-adjusted deviation from 0.5. The smooth curve avoids easy 0s and 100s. Grades: S ≥ 90, A ≥ 80, B ≥ 65, C ≥ 50, D ≥ 35, E below 35.</p><p>Same-scope comparisons exclude this commit, unscored history, and other score algorithms. Input attribution and task declarations remain local claims. The score is not a benchmark of developer ability or a security audit.</p><p><strong>Cumulative project score:</strong> starts at 0 and adds the existing score of each recorded commit exactly once. No additional weighting, thresholds, deductions, or tiers. The full first-parent history is included, not only the 30 visible rows. Commits without a recorded score add nothing.</p></div></div></details>
<footer class="footer"><div class="proof">PROOF ${esc(current.proof_hash)}<br>Local consistency ${data.demo?'illustrated':'checked'} · execution authenticity and complete capture are not attested.</div><div class="footer-brand">AI-PoW <span class="small">/ COMMIT RECORDS</span></div></footer>`;
function setView(view){document.body.classList.toggle('latest-only',view==='latest');$('#iteration').setAttribute('aria-pressed',String(view==='iteration'));$('#latest').setAttribute('aria-pressed',String(view==='latest'));try{history.replaceState(null,'','#'+view)}catch{}}
$('#iteration').addEventListener('click',()=>setView('iteration'));$('#latest').addEventListener('click',()=>setView('latest'));setView(data.view==='latest'||location.hash==='#latest'?'latest':'iteration');
let chartMode=ladder?'ladder':'scores';
function chart(){
  const isLadder=chartMode==='ladder';
  const rows=isLadder?[...data.history.filter(p=>p.iteration).reverse(),{...current,iteration:ladder}]:[...data.history.filter(p=>p.score&&p.score.algorithm===s.algorithm).reverse(),current];
  const value=p=>Number(isLadder?p.iteration?.value||0:p.score.value),values=rows.map(value);
  const low=0,high=isLadder?Math.max(100,Math.ceil((Math.max(0,...values)+20)/100)*100):100;
  const w=1060,h=225,left=isLadder?50:34,right=24,top=20,bottom=40,x=i=>left+(w-left-right)*i/Math.max(1,rows.length-1),y=v=>top+(h-top-bottom)*(1-(v-low)/(high-low));
  let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${isLadder?'Cumulative project score':'Individual commit scores'} across recorded commits, with latest last">`;
  for(let v=isLadder?low:20;v<=high;v+=isLadder?Math.max(50,Math.ceil((high-low)/500)*100):20)svg+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#3a475c"/><text x="0" y="${y(v)+3}">${v}</text>`;
  if(rows.length>1)svg+=`<polyline points="${rows.map((p,i)=>`${x(i)},${y(value(p))}`).join(' ')}" fill="none" stroke="#eb9b39" stroke-width="2.5"/>`;
  rows.forEach((p,i)=>{const latest=i===rows.length-1;svg+=`<circle cx="${x(i)}" cy="${y(value(p))}" r="${latest?6:4}" fill="${latest?'#ffac4d':'#b7c9df'}"><title>${esc(p.commit.slice(0,7)+' · '+value(p)+' · '+p.title)}</title></circle>`;if(i===0||latest||rows.length<9)svg+=`<text x="${x(i)}" y="${h-12}" text-anchor="${latest?'end':i===0?'start':'middle'}">${latest?'LATEST':esc(p.commit.slice(0,7))}</text>`;if(latest)svg+=`<text x="${x(i)-10}" y="${y(value(p))-12}" text-anchor="end" style="fill:#ffac4d;font-weight:bold">${n(value(p))}</text>`});
  $('#chart').innerHTML=svg+'</svg>';$('#chart-label').textContent=isLadder?'CUMULATIVE SCORE / COMMIT-SUM-V1':'COMMIT SCORE / 100';$('#chart-ladder').setAttribute('aria-pressed',String(isLadder));$('#chart-scores').setAttribute('aria-pressed',String(!isLadder));
}
$('#chart-ladder').addEventListener('click',()=>{chartMode='ladder';chart()});$('#chart-scores').addEventListener('click',()=>{chartMode='scores';chart()});chart();
function journal(){const grade=$('#grade-filter').value,scope=$('#scope-filter').value,rows=data.history.filter(p=>(grade==='all'||p.score?.grade===grade)&&(scope==='all'||p.score?.cohort===s.cohort));$('#journal').innerHTML=rows.length?rows.map(p=>`<button class="history-row" data-commit="${esc(p.commit)}" aria-label="Inspect commit ${esc(p.commit.slice(0,7))}"><span class="hash">${esc(p.commit.slice(0,7))}</span><span class="subject">${esc(p.title)}</span><span class="date">${esc(date(p.date))}</span><span class="row-score">${p.score?esc(p.score.value):'—'}${p.iteration?`<small class="row-rating">${n(p.iteration.value)} TOTAL</small>`:''}</span><span class="row-grade">${p.score?esc(p.score.grade):'N/A'}</span></button>`).join(''):'<p class="empty">'+(data.history.length?'No commits match these filters.':'No previous commits yet. Your next report can start the trend.')+'</p>';document.querySelectorAll('.history-row').forEach(button=>button.addEventListener('click',()=>inspect(data.history.find(p=>p.commit===button.dataset.commit))))}journal();$('#grade-filter').addEventListener('change',journal);$('#scope-filter').addEventListener('change',journal);
function inspect(p){const dialog=$('#commit-dialog');$('#dialog-body').innerHTML=`<span class="eyebrow">Historical commit · ${esc(p.commit.slice(0,10))}</span><h2>${esc(p.title)}</h2><div class="dialog-score">${p.score?esc(p.score.value):'—'} <span class="grade">${p.score?esc(p.score.grade):'?'}</span></div><p class="small">${p.score?esc(p.score.cohort)+' scope · '+pct(p.score.confidence)+' evidence confidence':'No AI-PoW proof was recorded for this commit.'}</p><p class="small">${esc(date(p.date))}</p>${p.iteration?`<p class="small">Cumulative score: ${n(p.iteration.value)} · +${n(p.iteration.delta)} this commit</p>`:''}<p class="small">The latest commit stays the main report. This panel only inspects a prior version.</p>`;dialog.showModal()}
$('#close-dialog').addEventListener('click',()=>$('#commit-dialog').close());$('#print').addEventListener('click',()=>window.print());$('#copy-commit').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(current.commit);notify('Commit hash copied')}catch{notify('Commit: '+current.commit)}});function notify(message){const t=$('#toast');t.textContent=message;t.hidden=false;setTimeout(()=>{t.hidden=true},4500)}
"""


def render(data):
    payload = json.dumps(data, ensure_ascii=True, separators=(",", ":")).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    script_hash = base64.b64encode(hashlib.sha256(JS.encode()).digest()).decode()
    return ("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
            + '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'sha256-' + script_hash
            + '\'; style-src \'unsafe-inline\'; img-src data:; base-uri \'none\'; form-action \'none\'">'
            + "<title>AI-PoW · Commit report</title><style>" + CSS + "</style></head><body>"
            + '<a class="skip" href="#content">Skip to report</a><header class="mast"><div class="wrap"><div class="logo"><span class="mark" aria-hidden="true"><i></i><i></i></span>AI-PoW<span class="edition"> / COMMIT REPORT</span></div><div class="top-actions"><span class="edition">BUILD RECORD / 03</span><button class="quiet" id="print">Print / PDF</button></div></div></header>'
            + '<main class="wrap" id="content"></main><noscript>This report requires JavaScript to display its embedded data. Use aipow report for the JSON version.</noscript>'
            + '<dialog id="commit-dialog" aria-label="Historical commit details"><header><span class="eyebrow">Commit inspection</span><button class="quiet" id="close-dialog">Close</button></header><div id="dialog-body"></div></dialog><div id="toast" class="toast" role="status" hidden></div>'
            + '<script id="report-data" type="application/json">' + payload + '</script><script>' + JS + '</script></body></html>')
